#nullable enable // autogenerated

using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 撑杆跳僵尸的动画行为：
    /// - 出场冲刺（还没跳、活着、走路中）：手臂层切换为"持杆待机"（ArmState = 10001）。
    /// - 跳跃中：手臂层切换为"撑杆跳跃"（ArmState = 10002，优先级最高）。
    /// - 落地跳完：交还原版逻辑（手臂回到 humanoid idle）。
    /// 对应控制器 Arm 层的 PoleIdle / PoleJump 两个状态。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.poleVaultingZombie_Animation)]
    public class PoleVaultingZombie_AnimationBehaviour : HumanoidAnimationBehaviour
    {
        public PoleVaultingZombie_AnimationBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override void ModifyAnimationParameters(Entity entity, int state, ref AnimationParameters parameters)
        {
            base.ModifyAnimationParameters(entity, state, ref parameters);
            if (PoleVaultingZombie.IsJumping(entity))
            {
                parameters.armState = PoleVaultingZombie.POLE_ARM_JUMP;
            }
            else if (!entity.IsDead && PoleVaultingZombie.GetPoleCount(entity) > 0 && state == STATE_WALK)
            {
                parameters.armState = PoleVaultingZombie.POLE_ARM_IDLE;
            }
        }
    }
}
